def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {}
    for row in grid:
        for v in row:
            if v != 0:
                colors[v] = colors.get(v, 0) + 1

    # The distinctive object color is the least frequent nonzero color.
    color = min(colors, key=colors.get)
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == color]

    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = {(r - r0, c - c0) for r, c in points}
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1

    out = [row[:] for row in grid]
    for top in range(h - sh + 1):
        for left in range(w - sw + 1):
            if all(grid[top + dr][left + dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[top + dr][left + dc] = color

    return out
